// Merge script: injects missing i18n keys into all 9 translation files.
// Usage: KMP_DUPLICATE_LIB_OK=TRUE node scripts/i18n-keys.js   (run from frontend/)
// - Each entry: [en, hi, ta, bn, te, mr, gu, kn, ml]; null => English fallback (flagged).
// - Idempotent: existing keys are never overwritten. Appends before final closing brace.
// - Also writes scripts/i18n-fallbacks.json (English-fallback pairs per language) for the Part D report.

const fs = require('fs');
const path = require('path');

const LANGS = ['en', 'hi', 'ta', 'bn', 'te', 'mr', 'gu', 'kn', 'ml'];

const translationsDir = path.join(__dirname, '..', 'src', 'i18n', 'translations');

// entries[key] = [en, hi, ta, bn, te, mr, gu, kn, ml]
const entries = {};

function add(key, values) {
  if (values.length !== LANGS.length) {
    throw new Error(`Key ${key} has ${values.length} values, expected ${LANGS.length}`);
  }
  entries[key] = values;
}

// === ENTRIES_START (append-only region) ===

