add('empty.products.title', ['Add your first craft product to get started', 'अपनी पहली हस्तशिल्प कला जोड़ें', 'உங்கள் முதல் கைவினை பொருளைச் சேர்த்துத் தொடங்குங்கள்', 'শুরু করতে আপনার প্রথম কুটিরশিল্প পণ্য যোগ করুন', 'ప్రారంభించడానికి మీ మొదటి చేతిపని ఉత్పత్తిని జోడించండి', 'सुरुवात करण्यासाठी तुमचे पहिले हस्तकला उत्पादन जोडा', 'શરૂ કરવા તમારું પહેલું હસ્તકલા ઉત્પાદન ઉમેરો', 'ಪ್ರಾರಂಭಿಸಲು ನಿಮ್ಮ ಮೊದಲ ಕೈಕಸಬು ಉತ್ಪನ್ನವನ್ನು ಸೇರಿಸಿ', 'ആരംഭിക്കാൻ നിങ്ങളുടെ ആദ്യ കൈവേല്പ് ഉൽപ്പന്നം ചേർക്കുക']);
add('empty.products.desc', ['Capture a photo or speak about your craft to publish an authentic listing in seconds.', 'अपनी कला का फोटो लें या बोलकर बताएं। एआई तुरंत आपकी लिस्टिंग तैयार करेगा।', 'உங்கள் கைவினையின் புகைப்படம் எடுங்கள் அல்லது பேசிக் கூறுங்கள். AI சில நிமிடங்களில் உங்கள் பட்டியலை உருவாக்கும்.', 'আপনার শিল্পকর্মের ছবি তুলুন বা বলে জানান। AI কয়েক সেকেন্ডে আপনার লিস্টিং তৈরি করবে।', 'మీ కళ ఫోటో తీయండి లేదా మాటల్లో చెప్పండి. AI క్షణాల్లో మీ లిస్టింగ్ సిద్ధం చేస్తుంది.', 'तुमच्या कलेचा फोटो घ्या किंवा बोलून सांगा. AI क्षणांत तुमची यादी तयार करेल.', 'તમારી કલાનો ફોટો લો અથવા બોલીને કહો. AI ક્ષણોમાં તમારી લિસ્ટિંગ તૈયાર કરશે.', 'ನಿಮ್ಮ ಕಲೆಯ ಫೋಟೋ ತೆಗೆಯಿರಿ ಅಥವಾ ಮಾತನಾಡಿ ಹೇಳಿ. AI ಕ್ಷಣಗಳಲ್ಲಿ ನಿಮ್ಮ ಪಟ್ಟಿಯನ್ನು ಸಿದ್ಧಗೊಳಿಸುತ್ತದೆ.', 'നിങ്ങളുടെ കലയുടെ ഫോട്ടോ എടുക്കുക അല്ലെങ്കിൽ പറഞ്ഞ് പറയുക. AI നിമിഷങ്ങൾക്കുള്ളിൽ നിങ്ങളുടെ ലിസ്റ്റിംഗ് തയ്യാറാക്കും.']);
add('empty.inquiries.title', ['No buyer inquiries yet', 'अभी कोई खरीदार पूछताछ नहीं है', 'இன்னும் வாங்குபவர் விசாரணைகள் இல்லை', 'এখনও কোনো ক্রেতার জিজ্ঞাসা নেই', 'ఇంకా కొనుగోలుదారు విచారణలు లేవు', 'अजून एखादी ग्राहक चौकशी नाही', 'હજુ કોઈ ખરીદદાર પૂછપરછ નથી', 'ಇನ್ನೂ ಯಾವುದೇ ಗ್ರಾಹಕ ವಿಚಾರಣೆಗಳಿಲ್ಲ', 'ഇതുവരെ വാങ്ങുന്നയാളുടെ അന്വേഷണങ്ങളില്ല']);
add('empty.inquiries.desc', ['When buyers across India and abroad discover your crafts, their inquiries will land here.', 'जब देश-विदेश के खरीदार आपके शिल्प देखेंगे, उनके संदेश यहाँ दिखाई देंगे।', 'இந்தியா மற்றும் வெளிநாடுகளில் உள்ள வாங்குபவர்கள் உங்கள் கைவினைகளைக் கண்டறிந்தால், அவர்களின் விசாரணைகள் இங்கே தோன்றும்.', 'ভারত ও বিদেশের ক্রেতারা আপনার শিল্পকর্ম আবিষ্কার করলে তাদের জিজ্ঞাসা এখানে দেখা যাবে।', 'భారతదేశం మరియు విదేశాల కొనుగోలుదారులు మీ చేతిపనులను కనుగొన్నప్పుడు, వారి విచారణలు ఇక్కడ కనిపిస్తాయి.', 'देश-विदेशातील ग्राहक तुमची कला पाहताच त्यांच्या चौकशी येथे दिसतील.', 'દેશ-વિદેશના ખરીદદારો તમારી કલા જોશે ત્યારે તેમની પૂછપરછ અહીં દેખાશે.', 'ಭಾರತ ಮತ್ತು ವಿದೇಶಗಳ ಗ್ರಾಹಕರು ನಿಮ್ಮ ಕೈಕಸಬು ಕಂಡುಕೊಂಡಾಗ, ಅವರ ವಿಚಾರಣೆಗಳು ಇಲ್ಲಿ ಕಾಣಿಸುತ್ತವೆ.', 'ഇന്ത്യയിലും വിദേശത്തുമുള്ള വാങ്ങുന്നവർ നിങ്ങളുടെ കൈവേല്പുകൾ കണ്ടെത്തുമ്പോൾ, അവരുടെ അന്വേഷണങ്ങൾ ഇവിടെ ദൃശ്യമാകും.']);
add('empty.products.cta', ['Add Product', 'पहला उत्पाद जोड़ें', 'பொருளைச் சேர்', 'পণ্য যোগ করুন', 'ఉత్పత్తిని జోడించండి', 'उत्पादन जोडा', 'ઉત્પાદન ઉમેરો', 'ಉತ್ಪನ್ನ ಸೇರಿಸಿ', 'ഉൽപ്പന്നം ചേർക്കുക']);
