add('perm.camera.title', ['Camera Permission Required', 'कैमरा अनुमति आवश्यक है', 'கேமரா அனுமதி தேவை', 'ক্যামেরার অনুমতি প্রয়োজন', 'కెమెరా అనుమతి అవసరం', 'कॅमेरा परवानगी आवश्यक आहे', 'કેમેરા પરવાનગી જરૂરી છે', 'ಕ್ಯಾಮೆರಾ ಅನುಮತಿ ಅಗತ್ಯವಿದೆ', 'ക്യാമറ അനുമതി ആവശ്യമാണ്']);
add('perm.mic.title', ['Microphone Permission Required', 'माइक्रोफ़ोन अनुमति आवश्यक है', 'மைக்ரோஃபோன் அனுமதி தேவை', 'মাইক্রোফোনের অনুমতি প্রয়োজন', 'మైక్రోఫోన్ అనుమతి అవసరం', 'मायक्रोफोन परवानगी आवश्यक आहे', 'માઇક્રોફોન પરવાનગી જરૂરી છે', 'ಮೈಕ್ರೋಫೋನ್ ಅನುಮತಿ ಅಗತ್ಯವಿದೆ', 'മൈക്ക് അനുമതി ആവശ്യമാണ്']);
add('perm.camera.desc', ['ShilpKala needs camera access so you can photograph your authentic handcrafted products.', 'शिल्पकला को आपके हस्तशिल्प की तस्वीरें लेने के लिए कैमरे की अनुमति की आवश्यकता है।', 'உங்கள் அசல் கைவினைப் பொருட்களின் புகைப்படம் எடுக்க ஷில்ப்கலாவுக்கு கேமரா அணுகல் தேவை.', 'আপনার প্রামাণিক হস্তশিল্পের ছবি তুলতে শিল্পকলার ক্যামেরা অ্যাক্সেস প্রয়োজন।', 'మీ అసలైన చేతిపనుల ఫోటోలు తీయడానికి షిల్ప్‌కాలాకు కెమెరా యాక్సెస్ అవసరం.', 'तुमच्या अस्सल हस्तकला उत्पादनांचे छायाचित्र घेण्यासाठी शिल्पकलाला कॅमेरा प्रवेश आवश्यक आहे.', 'તમારા અસલી હસ્તકલા ઉત્પાદનોના ફોટા લેવા શિલ્પકલાને કેમેરા પ્રવેશ જોઈએ.', 'ನಿಮ್ಮ ಅಧಿಕೃತ ಕೈಕಸಬು ಉತ್ಪನ್ನಗಳ ಫೋಟೋ ತೆಗೆಯಲು ಶಿಲ್ಪಕಾಲಾಕ್ಕೆ ಕ್ಯಾಮೆರಾ ಪ್ರವೇಶ ಬೇಕು.', 'നിങ്ങളുടെ യഥാർത്ഥ കൈവേല്പ് ഉൽപ്പന്നങ്ങളുടെ ഫോട്ടോ എടുക്കാൻ ഷിൽപ്കലയ്ക്ക് ക്യാമറ ആക്സസ് വേണം.']);
add('perm.mic.desc', ['ShilpKala needs microphone access to capture voice descriptions and record buyer voice responses.', 'शिल्पकला को आपकी मातृभाषा में शिल्प का विवरण और वॉयस जवाब रिकॉर्ड करने के लिए माइक की अनुमति चाहिए।', 'குரல் விவரங்களைப் பிடிக்கவும் வாங்குபவர்களின் குரல் பதில்களைப் பதிவு செய்யவும் ஷில்ப்கலாவுக்கு மைக்ரோஃபோன் அணுகல் தேவை.', 'ভয়েস বিবরণ ধরতে এবং ক্রেতার ভয়েস উত্তর রেকর্ড করতে শিল্পকলার মাইক্রোফোন অ্যাক্সেস প্রয়োজন।', 'వాయిస్ వివరణలను సంగ్రహించడం మరియు కొనుగోలుదారు వాయిస్ ప్రతిస్పందనలను రికార్డ్ చేయడానికి షిల్ప్‌కాలాకు మైక్రోఫోన్ యాక్సెస్ అవసరం.', 'आवाजातील वर्णने नोंदवण्यासाठी आणि ग्राहकांची आवाजातील उत्तरे रेकॉर्ड करण्यासाठी शिल्पकलाला मायक्रोफोन प्रवेश हवा आहे.', 'વૉઇસ વર્ણનો કેપ્ચર કરવા અને ખરીદદારોના વૉઇસ જવાબો રેકોર્ડ કરવા શિલ્પકલાને માઇક્રોફોન પ્રવેશ જોઈએ.', 'ಧ್ವನಿ ವಿವರಣೆಗಳನ್ನು ಸೆರೆಹಿಡಿಯಲು ಮತ್ತು ಗ್ರಾಹಕರ ಧ್ವನಿ ಪ್ರತಿಕ್ರಿಯೆಗಳನ್ನು ರೆಕಾರ್ಡ್ ಮಾಡಲು ಶಿಲ್ಪಕಾಲಾಕ್ಕೆ ಮೈಕ್ರೋಫೋನ್ ಪ್ರವೇಶ ಬೇಕು.', 'വോയ്സ് വിവരണങ്ങൾ പിടിച്ചെടുക്കാനും വാങ്ങുന്നവരുടെ വോയ്സ് മറുപടികൾ റെക്കോർഡ് ചെയ്യാനും ഷിൽപ്കലയ്ക്ക് മൈക്ക് ആക്സസ് വേണം.']);
add('perm.enableInSettings', ['Enable in device settings', 'सेटिंग्स में जाकर अनुमति चालू करें', 'சாதன அமைப்புகளில் இயக்கவும்', 'ডিভাইস সেটিংসে চালু করুন', 'పరికర సెట్టింగ్‌లలో ప్రారంభించండి', 'डिव्हाइस सेटिंग्जमध्ये चालू करा', 'ડિવાઇસ સેટિંગ્સમાં ચાલુ કરો', 'ಸಾಧನ ಸೆಟ್ಟಿಂಗ್‌ಗಳಲ್ಲಿ ಸಕ್ರಿಯಗೊಳಿಸಿ', 'ഉപകരണ സെറ്റിംഗ്സിൽ പ്രവർത്തനക്ഷമമാക്കുക']);
add('perm.openSettings', ['Open Settings', 'सेटिंग्स खोलें', 'அமைப்புகளைத் திற', 'সেটিংস খুলুন', 'సెట్టింగ్‌లను తెరవండి', 'सेटिंग्ज उघडा', 'સેટિંગ્સ ખોલો', 'ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ತೆರೆಯಿರಿ', 'സെറ്റിംഗ്സ് തുറക്കുക']);
add('perm.tryAgain', ['Try Again', 'पुनः अनुमति मांगें', 'மீண்டும் முயற்சிக்கவும்', 'আবার চেষ্টা করুন', 'మళ్లీ ప్రయత్నించండి', 'पुन्हा प्रयत्न करा', 'ફરી પ્રયાસ કરો', 'ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ', 'വീണ്ടും ശ്രമിക്കുക']);
