add('not.n1.title', ['New Buyer Inquiry', 'नई खरीदार पूछताछ', 'புதிய வாங்குபவர் விசாரணை', 'নতুন ক্রেতার জিজ্ঞাসা', 'కొత్త కొనుగోలుదారు విచారణ', 'नवीन ग्राहक चौकशी', 'નવી ખરીદદાર પૂછપરછ', 'ಹೊಸ ಗ್ರಾಹಕ ವಿಚಾರಣೆ', 'പുതിയ വാങ്ങുന്നയാളുടെ അന്വേഷണം']);
add('not.n1.message', ['Elena Rostova (Berlin) sent a wholesale inquiry for 50 Banarasi Silk Sarees.', 'एलेना रोस्तोवा (बर्लिन) ने 50 बनारसी सिल्क साड़ियों के लिए थोक पूछताछ भेजी है।', 'எலெனா ரோஸ்டோவா (பெர்லின்) 50 பனாரஸ் பட்டுச் சேலைகளுக்கு மொத்த விற்பனை விசாரணை அனுப்பியுள்ளார்.', 'এলেনা রোস্তোভা (বার্লিন) ৫০টি বেনারসি সিল্ক শাড়ির জন্য পাইকারি জিজ্ঞাসা পাঠিয়েছেন।', 'ఎలెనా రోస్టోవా (బెర్లిన్) 50 బనారసీ సిల్క్ చీరలకు హోల్‌సేల్ విచారణ పంపారు.', 'एलेना रोस्तोव्हा (बर्लिन) यांनी ५० बनारसी सिल्क साड़्यांसाठी घाऊक चौकशी पाठवली आहे.', 'એલેના રોસ્ટોવા (બર્લિન) એ 50 બનારસી સિલ્ક સાડીઓ માટે જથ્થાબંધ પૂછપરછ મોકલી છે.', 'ಎಲೆನಾ ರೋಸ್ಟೋವಾ (ಬರ್ಲಿನ್) 50 ಬನಾರಸಿ ಸಿಲ್ಕ್ ಸೀರೆಗಳಿಗೆ ಸಗಟು ವಿಚಾರಣೆ ಕಳುಹಿಸಿದ್ದಾರೆ.', 'എലെന റോസ്റ്റോവ (ബെർലിൻ) 50 ബനാറസി സിൽക്ക് സാരികൾക്ക് മൊത്തക്കച്ചവർത്തന അന്വേഷണം അയച്ചിട്ടുണ്ട്.']);
add('not.n2.title', ['Product Live on Catalog', 'उत्पाद स्टोरफ्रंट पर लाइव', 'பொருள் கேட்டலாகில் நேரடியில்', 'পণ্য ক্যাটালগে লাইভ', 'ఉత్పత్తి కేటలాగ్‌లో లైవ్', 'उत्पादन कॅटलॉगवर लाइव्ह', 'ઉત્પાદન કેટેલોગ પર લાઇવ', 'ಉತ್ಪನ್ನ ಕ್ಯಾಟಲಾಗ್‌ನಲ್ಲಿ ಲೈವ್', 'ഉൽപ്പന്നം കാറ്റലോഗിൽ ലൈവ്']);
add('not.n2.message', ['Your Banarasi Pure Silk Saree is now live on your catalog and searchable worldwide.', 'आपकी बनारसी शुद्ध रेशम साड़ी अब खरीदारों के लिए लाइव और खोजी जा सकती है।', 'உங்கள் பனாரஸ் தூய பட்டுச் சேலை இப்போது உங்கள் பட்டியலில் நேரடியாக உள்ளது, உலகளவில் தேடக்கூடியது.', 'আপনার বেনারসি খাঁটি সিল্ক শাড়ি এখন আপনার ক্যাটালগে লাইভ এবং সারা বিশ্বে অনুসন্ধানযোগ্য।', 'మీ బనారసీ స్వచ్ఛ సిల్క్ చీర ఇప్పుడు మీ కేటలాగ్‌లో లైవ్‌లో ఉంది మరియు ప్రపంచవ్యాప్తంగా శోధించదగినది.', 'तुमची बनारसी शुद्ध रेशमी साड़ी आता तुमच्या कॅटलॉगवर लाइव्ह आहे आणि जगभर शोधता येते.', 'તમારી બનારસી શુદ્ધ સિલ્ક સાડી હવે તમારા કેટેલોગ પર લાઇવ છે અને વિશ્વભરમાં શોધી શકાય છે.', 'ನಿಮ್ಮ ಬನಾರಸಿ ಶುದ್ಧ ರೇಷ್ಮೆ ಸೀರೆ ಈಗ ನಿಮ್ಮ ಕ್ಯಾಟಲಾಗ್‌ನಲ್ಲಿ ಲೈವ್ ಆಗಿದೆ ಮತ್ತು ವಿಶ್ವಾದ್ಯಂತ ಹುಡುಕಬಹುದು.', 'നിങ്ങളുടെ ബനാറസി ശുദ്ധ സിൽക്ക് സാരി ഇപ്പോൾ നിങ്ങളുടെ കാറ്റലോഗിൽ ലൈവ് ആണ്, ലോകമെമ്പാടും തിരയാവുന്നതാണ്.']);
add('not.n3.title', ['GI Authenticity Verification Complete', 'जीआई प्रामाणिकता सत्यापन सफल', 'GI நேர்மை சரிபார்ப்பு முடிந்தது', 'GI সত্যতা যাচাই সম্পন্ন', 'GI అసలుతన ధృవీకరణ పూర్తి', 'GI अस्सलपणा पडताळणी पूर्ण', 'GI અસલિયત ચકાસણી પૂર્ણ', 'GI ಅಧಿಕೃತತೆ ಪರಿಶೀಲನೆ ಪೂರ್ಣ', 'GI ആധികാരികത സ്ഥിരീകരണം പൂർത്തിയായി']);
add('not.n3.message', ['Banaras Brocades & Sarees (GI Reg #99) verified under official Govt GI Registry.', 'बनारस ब्रोकेड्स और साड़ियाँ (GI Reg #99) आधिकारिक सरकारी रजिस्ट्री से सत्यापित हुआ।', 'பனாரஸ் ப்ரோகேட்ஸ் & சேலைகள் (GI Reg #99) அதிகாரப்பூர்வ அரசு GI பதிவேட்டில் சரிபார்க்கப்பட்டது.', 'বেনারস ব্রোকেড ও শাড়ি (GI Reg #99) সরকারি GI রেজিস্ট্রিতে যাচাই করা হয়েছে।', 'బనారస్ బ్రోకేడ్స్ & చీరలు (GI Reg #99) అధికారిక ప్రభుత్వ GI రిజిస్ట్రీలో ధృవీకరించబడింది.', 'बनारस ब्रोकेड्स व साड़्या (GI Reg #99) अधिकृत शासकीय GI नोंदणीत पडताळले.', 'બનારસ બ્રોકેડ્સ અને સાડીઓ (GI Reg #99) સત્તાવાર સરકારી GI રજિસ્ટ્રીમાં ચકાસાયેલ છે.', 'ಬನಾರಸ್ ಬ್ರೋಕೇಡ್ಸ್ & ಸೀರೆಗಳು (GI Reg #99) ಅಧಿಕೃತ ಸರ್ಕಾರಿ GI ನೋಂದಣಿಯಲ್ಲಿ ಪರಿಶೀಲಿಸಲಾಗಿದೆ.', 'ബനാറസ് ബ്രോക്കേഡ്സ് & സാരികൾ (GI Reg #99) ഔദ്യോഗിക സർക്കാർ GI രജിസ്ട്രിയിൽ സ്ഥിരീകരിച്ചു.']);
add('not.n4.title', ['3 Products Still in Draft', '३ उत्पाद ड्राफ्ट में हैं', '3 பொருட்கள் இன்னும் வரைவில்', '3টি পণ্য এখনও খসড়ায়', '3 ఉత్పత్తులు ఇంకా డ్రాఫ్ట్‌లో', '३ उत्पादने अजून मसुद्यात', '3 ઉત્પાદનો હજુ ડ્રાફ્ટમાં', '3 ಉತ್ಪನ್ನಗಳು ಇನ್ನೂ ಕರಡಿನಲ್ಲಿ', '3 ഉൽപ്പന്നങ്ങൾ ഇപ്പോഴും ഡ്രാഫ്റ്റിൽ']);
add('not.n4.message', ['You have 3 crafts in draft. Complete them to reach verified buyers worldwide.', 'आपके ३ हस्तशिल्प ड्राफ्ट में हैं। इन्हें पूरा करके सीधे वैश्विक खरीदारों तक पहुंचें।', 'உங்களுடைய 3 கைவினைப் பொருட்கள் வரைவில் உள்ளன. சரிபார்க்கப்பட்ட வாங்குபவர்களை உலகளவில் அடைய அவற்றை முடிக்கவும்.', 'আপনার ৩টি কুটিরশিল্প খসড়ায় আছে। বিশ্বজুড়ে যাচাইকৃত ক্রেতাদের কাছে পৌঁছাতে সেগুলি সম্পূর্ণ করুন।', 'మీరు 3 చేతిపనులు డ్రాఫ్ట్‌లో కలిగి ఉన్నారు. ప్రపంచవ్యాప్తంగా ధృవీకరించిన కొనుగోలుదారులను చేరుకోవడానికి వాటిని పూర్తి చేయండి.', 'तुमच्या ३ हस्तकला मसुद्यात आहेत. जगभर पडताळलेल्या ग्राहकांपर्यंत पोहोचण्यासाठी त्या पूर्ण करा.', 'તમારી પાસે 3 હસ્તકલા ડ્રાફ્ટમાં છે. વિશ્વભરના ચકાસાયેલ ખરીદદારો સુધી પહોંચવા તેમને પૂર્ણ કરો.', 'ನಿಮ್ಮ 3 ಕೈಕಸಬು ಕರಡಿನಲ್ಲಿವೆ. ವಿಶ್ವಾದ್ಯಂತ ಪರಿಶೀಲಿತ ಗ್ರಾಹಕರನ್ನು ತಲುಪಲು ಅವುಗಳನ್ನು ಪೂರ್ಣಗೊಳಿಸಿ.', 'നിങ്ങളുടെ 3 കൈവേല്പുകൾ ഡ്രാഫ്റ്റിലുണ്ട്. ലോകമെമ്പാടുമുള്ള സ്ഥിരീകരിച്ച വാങ്ങുന്നവരിലേക്ക് എത്താൻ അവ പൂർത്തിയാക്കുക.']);
