add('lr.loadingSub', ['Analyzing your voice description and product image...', 'कारीगर के ध्वनि विवरण एवं उत्पाद छवि का एआई विश्लेषण जारी है...', 'உங்கள் குரல் விவரம் மற்றும் பொருள் படம் பகுப்பாய்வு செய்யப்படுகிறது...', 'আপনার ভয়েস বিবরণ ও পণ্যের ছবি বিশ্লেষণ চলছে...', 'మీ వాయిస్ వివరణ మరియు ఉత్పత్తి చిత్రం విశ్లేషణ జరుగుతోంది...', 'तुमच्या आवाजातील वर्णन व उत्पादन प्रतिमेचे विश्लेषण सुरू आहे...', 'તમારા વૉઇસ વર્ણન અને ઉત્પાદન ઈમેજનું વિશ્લેષણ ચાલુ છે...', 'ನಿಮ್ಮ ಧ್ವನಿ ವಿವರಣೆ ಮತ್ತು ಉತ್ಪನ್ನ ಚಿತ್ರದ ವಿಶ್ಲೇಷಣೆ ನಡೆಯುತ್ತಿದೆ...', 'നിങ്ങളുടെ വോയ്സ് വിവരണവും ഉൽപ്പന്ന ചിത്രവും വിശകലനം ചെയ്യപ്പെടുന്നു...']);
add('lr.errorHeading', ['Generation Notice', 'विवरण उत्पन्न करने में समस्या', 'உருவாக்க அறிவிப்பு', 'তৈরিতে সমস্যা', 'రూపకల్పన నోటీసు', 'निर्मिती सूचना', 'જનરેશન નોટિસ', 'ರಚನೆ ಸೂಚನೆ', 'ജനറേഷൻ നോട്ടീസ്']);
add('lr.errorBody', ['Could not reach the server ({error}). Please try again.', 'सर्वर से संपर्क नहीं हो पाया ({error})। कृपया पुनः प्रयास करें।', 'சர்வரை அணுக முடியவில்லை ({error}). மீண்டும் முயற்சிக்கவும்.', 'সার্ভারে সংযোগ করা যায়নি ({error})। আবার চেষ্টা করুন।', 'సర్వర్‌ను సంప్రదించలేకపోయాము ({error}). దయచేసి మళ్లీ ప్రయత్నించండి.', 'सर्व्हरशी संपर्क होऊ शकला नाही ({error}). कृपया पुन्हा प्रयत्न करा.', 'સર્વરનો સંપર્ક થઈ શક્યો નથી ({error}). ફરી પ્રયાસ કરો.', 'ಸರ್ವರ್ ಸಂಪರ್ಕ ಸಾಧಿಸಲಾಗಲಿಲ್ಲ ({error}). ದಯವಿಟ್ಟು ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.', 'സർവറുമായി ബന്ധപ്പെടാനായില്ല ({error}). ദയവായി വീണ്ടും ശ്രമിക്കുക.']);
add('lr.retryAI', ['Retry AI', 'पुनः प्रयास करें', 'மீண்டும் முயற்சி', 'আবার চেষ্টা করুন', 'మళ్లీ ప్రయత్నించండి', 'पुन्हा प्रयत्न करा', 'ફરી પ્રયાસ કરો', 'ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ', 'വീണ്ടും ശ്രമിക്കുക']);
