add('sp.engineSub', ['Fair Heritage Pricing Engine • Rules-Based Heuristic v1', 'निष्पक्ष धरोहर मूल्य इंजन • नियम-आधारित ह्यूरिस्टिक v1', 'நேர்மையான பாரம்பரிய விலை இயந்திரம் • விதி அடிப்படையிலான ஹ்யூரிஸ்டிக் v1', 'ন্যায্য ঐতিহ্য মূল্য ইঞ্জিন • নিয়ম-ভিত্তিক হিউরিস্টিক v1', 'న్యాయమైన వారసత్వ ధర ఇంజన్ • నియమ-ఆధారిత హ్యూరిస్టిక్ v1', 'गोष्ट हस्तकला किंमत इंजिन • नियम-आधारित ह्युरिस्टिक v1', 'વાજબી વારસાકી કિંમત એન્જિન • નિયમ-આધારિત હ્યુરિસ્ટિક v1', 'ನ್ಯಾಯವಾದ ಪರಂಪರೆ ಬೆಲೆ ಎಂಜಿನ್ • ನಿಯಮ-ಆಧಾರಿತ ಹ್ಯೂರಿಸ್ಟಿಕ್ v1', 'നീതിയുക്ത പൈതൃക വില എഞ്ചിൻ • നിയമ-അടിസ്ഥാന ഹ്യൂറിസ്റ്റിക് v1']);
add('sp.defaultCitation', ['Based on Ministry of Textiles cost guidelines and artisan wage standards', 'वस्त्र मंत्रालय लागत दिशा-निर्देशों एवं कारीगर मजदूरी मानकों पर आधारित', 'ஜவுளி அமைச்சக செலவு வழிகாட்டுதல்கள் மற்றும் கைவினைஞர் ஊதிய தரங்களின் அடிப்படையில்', 'বস্ত্র মন্ত্রকের খরচ নির্দেশিকা ও কারিগর মজুরি মানদণ্ডের ভিত্তিতে', 'వస్త్ర మంత్రిత్వ శాఖ ఖర్చు మార్గదర్శకాలు మరియు కళాకారుల వేతన ప్రమాణాల ఆధారంగా', 'वस्त्र मंत्रालय खर्च मार्गदर्शक तत्त्वे व कारागीर मजदुरी मानकांवर आधारित', 'કાપડ મંત્રાલય ખર્ચ માર્ગદર્શિકા અને કારીગર મજૂરી ધોરણો પર આધારિત', 'ವಸ್ತ್ರ ಸಚಿವಾಲಯ ವೆಚ್ಚ ಮಾರ್ಗಸೂಚಿಗಳು ಮತ್ತು ಕುಶಲಕರ್ಮಿ ಕೂಲಿ ಮಾನದಂಡಗಳ ಆಧಾರಿತ', 'വസ്ത്ര മന്ത്രാലയ ചെലവ് മാർഗരേഖകളെയും ആർട്ടിസൻ കൂലി മാനദണ്ഡങ്ങളെയും ആധാരമാക്കി']);
add('sp.localModelNotice', ['Running on local transparent heuristic', 'स्थानीय पारदर्शी ह्यूरिस्टिक सक्रिय है', 'உள்ளூர் வெளிப்படையான ஹ்யூரிஸ்டிக் இயங்குகிறது', 'স্থানীয় স্বচ্ছ হিউরিস্টিক চলছে', 'స్థానిక పారదర్శక హ్యూరిస్టిక్ పనిచేస్తోంది', 'स्थानिक पारदर्शी ह्युरिस्टिवर चालू आहे', 'સ્થાનિક પારદર્શક હ્યુરિસ્ટિક પર ચાલુ છે', 'ಸ್ಥಳೀಯ ಪಾರದರ್ಶಕ ಹ್ಯೂರಿಸ್ಟಿಕ್ ಚಾಲನೆಯಲ್ಲಿದೆ', 'പ്രാദേശിക സുതാര്യ ഹ്യൂറിസ്റ്റിക് പ്രവർത്തിക്കുന്നു']);
add('sp.costHint', ['Price range auto-updates as material cost changes • Auto-calculates as you type or speak', 'सामग्री लागत बदलते ही मूल्य सीमा स्वचालित रूप से अपडेट होती है • Auto-calculates as you type or speak', 'பொருள் செலவு மாறும்போது விலை வரம்பு தானாகப் புதுப்பிக்கப்படும் • தட்டச்சு அல்லது பேசும்போது தானாகக் கணக்கிடப்படும்', 'উপকরণের খরচ পরিবর্তন হলে মূল্য পরিসর স্বয়ংক্রিয়ভাবে আপডেট হয় • টাইপ বা বলার সাথে সাথে হিসাব হয়', 'పదార్థ ఖర్చు మారినప్పుడు ధర పరిధి స్వయంచాలకంగా అప్‌డేట్ అవుతుంది • టైప్ చేసినా మాట్లాడినా స్వయంగా లెక్కవేస్తుంది', 'साहित्य खर्च बदलताच किंमत श्रेणी स्वयंचलित अद्ययावत होते • टाइप किंवा बोलताच आपोआप गणना होते', 'સામગ્રી ખર્ચ બદલાતાં કિંમત શ્રેણી આપોઆપ અપડેટ થાય છે • ટાઇપ કરો કે બોલો તેમ ગણતરી થાય', 'ವಸ್ತು ವೆಚ್ಚ ಬದಲಾದಂತೆ ಬೆಲೆ ಶ್ರೇಣಿ ಸ್ವಯಂಚಾಲಿತವಾಗಿ ನವೀಕರಿಸುತ್ತದೆ • ಟೈಪ್ ಮಾಡಿದಾಗ ಅಥವಾ ಮಾತನಾಡಿದಾಗ ಸ್ವಯಂ ಲೆಕ್ಕಾಚಾರ', 'വസ്തു ചെലവ് മാറുമ്പോൾ വില പരിധി സ്വയമേവ അപ്ഡേറ്റ് ചെയ്യും • ടൈപ്പ് ചെയ്യുമ്പോഴോ സംസാരിക്കുമ്പോഴോ സ്വയം കണക്കാക്കും']);
add('sp.honestyTitle', ['Honesty Disclosure', 'पारदर्शिता अनुबंध', 'வெளிப்படைத்தன்மை அறிவிப்பு', 'সততার প্রকাশ', 'పారదర్శకత ప్రకటన', 'प्रामाणिकपणा प्रकटीकरण', 'પ્રામાણિકતા પ્રગટીકરણ', 'ಪ್ರಾಮಾಣಿಕತೆ ಬಹಿರಂಗಪಡಿಸುವಿಕೆ', 'അഴിമതിരഹിത പ്രഖ്യാപനം']);
add('sp.defaultDisclaimer', ['This estimate is derived by rules based on Ministry of Textiles and fair-trade guidelines (cost × 2.4-3.4) plus GI certification premium (+30%). There is no hidden or closed algorithm.', 'यह अनुमान वस्त्र मंत्रालय एवं निष्पक्ष व्यापार दिशानिर्देशों (लागत × 2.4-3.4) एवं जीआई प्रमाणन प्रीमियम (+30%) पर आधारित नियमों द्वारा निकाला गया है। यह कोई गुप्त या बंद एल्गोरिदम नहीं है।', 'இந்த மதிப்பீடு ஜவுளி அமைச்சகம் மற்றும் நியாயமான வர்த்தக வழிகாட்டுதல்களின் (செலவு × 2.4-3.4) மற்றும் GI சான்றிதழ் பிரீமியம் (+30%) அடிப்படையிலான விதிகளால் பெறப்பட்டது. இது மறைக்கப்பட்ட அல்காரிதம் அல்ல.', 'এই অনুমান বস্ত্র মন্ত্রক ও ন্যায্য বাণিজ্য নির্দেশিকার (খরচ × ২.৪-৩.৪) এবং GI সার্টিফিকেশন প্রিমিয়াম (+৩০%) নিয়ম অনুসারে গণনা করা হয়েছে। এখানে কোনো গোপন অ্যালগরিদম নেই।', 'ఈ అంచనా వస్త్ర మంత్రిత్వ శాఖ మరియు న్యాయమైన వర్తక మార్గదర్శకాల (ఖర్చు × 2.4-3.4) మరియు GI ధృవీకరణ ప్రీమియం (+30%) నియమాల ద్వారా గణించబడింది. ఇది దాచిన అల్గారిథం కాదు.', 'हा अंदाज वस्त्र मंत्रालय व गोष्ट व्यवहार मार्गदर्शक तत्त्वांवर (खर्च × २.४-३.४) व GI प्रमाणपत्र प्रीमियम (+३०%) आधारित नियमांनुसार काढला आहे. येथे कोणतेही गुप्त अल्गोरिथम नाही.', 'આ અંદાજ કાપડ મંત્રાલય અને વાજબી વેપાર માર્ગદર્શિકા (ખર્ચ × 2.4-3.4) અને GI પ્રમાણપત્ર પ્રીમિયમ (+30%) નિયમો દ્વારા ગણવામાં આવે છે. અહીં કોઈ ગુપ્ત અલ્ગોરિધમ નથી.', 'ಈ ಅಂದಾಜು ವಸ್ತ್ರ ಸಚಿವಾಲಯ ಮತ್ತು ನ್ಯಾಯವಾದ ವ್ಯಾಪಾರ ಮಾರ್ಗಸೂಚಿಗಳ (ವೆಚ್ಚ × 2.4-3.4) ಮತ್ತು GI ಪ್ರಮಾಣಪತ್ರ ಪ್ರೀಮಿಯಂ (+30%) ನಿಯಮಗಳಿಂದ ಗಣಿಸಲಾಗಿದೆ. ಇಲ್ಲಿ ಯಾವುದೇ ಗುಪ್ತ ಅಲ್ಗಾರಿದಮ್ ಇಲ್ಲ.', 'ഈ കണക്കാക്കൽ വസ്ത്ര മന്ത്രാലയവും നീതിയുക്ത വ്യാപാര മാർഗരേഖകളും (ചെലവ് × 2.4-3.4) GI സർട്ടിഫിക്കേഷൻ പ്രീമിയവും (+30%) അടിസ്ഥാനമാക്കിയുള്ള നിയമങ്ങളാൽ കണക്കാക്കിയതാണ്. ഇവിടെ ഒരു രഹസ്യ അൽഗോരിതവുമില്ല.']);
add('sp.benchmarkFallback', ['Fair-trade reference', 'सहकारी संदर्भ', 'நியாயமான குறிப்பு', 'ন্যায্য রেফারেন্স', 'న్యాయమైన రిఫరెన్స్', 'गोष्ट संदर्भ', 'વાજબી સંદર્ભ', 'ನ್ಯಾಯವಾದ ಉಲ್ಲೇಖ', 'നീതിയുക്ത റഫറൻസ്']);

