const fallbackLedger = []; // { key, lang, value }

function mergeAll() {
  for (const lang of LANGS) {
    const filePath = path.join(translationsDir, `${lang}.js`);
    let src = fs.readFileSync(filePath, 'utf8');

    // Parse existing keys via a temp module (files are `export default {...}`)
    const tempPath = path.join(__dirname, `.tmp-${lang}.cjs`);
    fs.writeFileSync(tempPath, src.replace(/export default/, 'module.exports ='));
    delete require.cache[require.resolve(tempPath)];
    const dict = require(tempPath);
    fs.unlinkSync(tempPath);

    const missing = [];
    for (const [key, values] of Object.entries(entries)) {
      if (dict[key] !== undefined) continue;
      const idx = LANGS.indexOf(lang);
      let value = values[idx];
      if (value === null || value === undefined) {
        value = values[0]; // English fallback
        fallbackLedger.push({ key, lang, value });
      }
      missing.push([key, value]);
    }

    if (missing.length === 0) {
      console.log(`  ${lang}: already complete (${Object.keys(entries).length} keys checked)`);
      continue;
    }

    // Append before the final closing brace of the default-export object.
    const insertIdx = src.lastIndexOf('};');
    if (insertIdx === -1) throw new Error(`No closing brace found in ${lang}.js`);
    const block = missing
      .map(([k, v]) => `  ${JSON.stringify(k)}: ${JSON.stringify(v)},`)
      .join('\n');
    src = src.slice(0, insertIdx).replace(/,\s*$/, '') + ',\n' + block + '\n' + src.slice(insertIdx);
    fs.writeFileSync(filePath, src);
    console.log(`  ${lang}: +${missing.length} keys`);
  }
}

mergeAll();

if (fallbackLedger.length > 0) {
  const outPath = path.join(__dirname, 'i18n-fallbacks.json');
  fs.writeFileSync(outPath, JSON.stringify(fallbackLedger, null, 2));
  console.log(`\n${fallbackLedger.length} English-fallback pairs written to ${path.relative(process.cwd(), outPath)}`);
} else {
  console.log('\nZero English fallbacks — every key fully translated.');
}
console.log('Done.');
